R<-(function(x) { if (!nzchar(x)) stop("Set CANINE_CIE_PROJECT_ROOT"); x })(Sys.getenv("CANINE_CIE_PROJECT_ROOT"));O<-file.path(R,"WORKING","30_HUMAN_PSEUDOBULK_INDEX_CORRECTION");W<-file.path(O,"work");G<-file.path(R,"07_human_crohn","GSE266616","gsea","gene_sets")
P<-data.table(lineage=c(rep("Epithelial",3),rep("Myeloid",3)),frozen_program_id=c("Epithelial::Mitochondrial respiration","Epithelial::Oxidative phosphorylation","Epithelial::Xenobiotic metabolism","Myeloid::TNF / NF-kappaB","Myeloid::Inflammatory response","Myeloid::TLR4"),program=c("Mitochondrial respiration","Oxidative phosphorylation","Xenobiotic metabolism","TNF / NF-kappaB","Inflammatory response","TLR4"),collection=c("Reactome","GO_BP","Hallmark","Hallmark","GO_BP","Reactome"),pathway_id=c("R-HSA-1428517","GO:0006119","HALLMARK_XENOBIOTIC_METABOLISM","HALLMARK_TNFA_SIGNALING_VIA_NFKB","GO:0050727","R-HSA-166016"))
