slug<-function(x){y<-tolower(strsplit(x,"")[[1]]);y[!grepl("[a-z0-9]",y)]<-"_";gsub("^_+|_+$","",paste0(y,collapse=""))}
fit<-function(name,omit="NONE",untreated=FALSE,off=0){
 c<-fread(file.path(W,paste0("human_",slug(name),"_counts.tsv")));m<-fread(file.path(W,paste0("human_",slug(name),"_meta.tsv")));if(omit!="NONE")m<-m[donor!=omit];if(untreated)m<-m[condition=="Healthy"|tolower(biologic_treatment)%in%c("no","no_biologic","none","na","")]
 nh<-m[condition=="Healthy",uniqueN(donor)];nc<-m[condition=="ActiveCrohn",uniqueN(donor)];if(nh<5||nc<5)return(list(ok=FALSE,why="NON_ESTIMABLE_DONOR_GATE",nh=nh,nc=nc))
 ids<-m$sample_column;a<-c[,.(unique_gene_id,gene_symbol)];x<-as.matrix(c[,..ids]);storage.mode(x)<-"integer";rownames(x)<-a$unique_gene_id;m[,condition:=factor(condition,levels=c("Healthy","ActiveCrohn"))];d<-model.matrix(~condition,m);y<-DGEList(x);k<-filterByExpr(y,design=d);y<-y[k,,keep.lib.sizes=FALSE];y<-calcNormFactors(y);y<-estimateDisp(y,d,robust=TRUE);f<-glmQLFit(y,d,robust=TRUE);q<-glmQLFTest(f,coef="conditionActiveCrohn");raw<-topTags(q,n=Inf,sort.by="none")$table;t<-as.data.table(raw,keep.rownames="unique_gene_id");t[,rank:=sign(logFC)*sqrt(F)];t<-merge(t,a,by="unique_gene_id");t<-t[!is.na(gene_symbol)&nzchar(gene_symbol)&is.finite(rank)];t[,ar:=abs(rank)];setorder(t,gene_symbol,-ar,PValue,unique_gene_id);t<-t[,.SD[1],by=gene_symbol];s<-t$rank;names(s)<-t$gene_symbol;lin<-strsplit(name,"__",fixed=TRUE)[[1]][1];pp<-P[lineage==lin];paths<-split(mem[pathway_id%in%pp$pathway_id,gene_symbol],mem[pathway_id%in%pp$pathway_id,pathway_id]);set.seed(20261016+off);g<-as.data.table(fgseaMultilevel(paths,s,minSize=15,maxSize=500,eps=1e-10,nproc=1));setnames(g,"pathway","pathway_id");if(nrow(g)){g[,leading_edge_n:=lengths(leadingEdge)];g[,leadingEdge:=NULL]}else{g<-data.table(pathway_id=character(),ES=numeric(),NES=numeric(),pval=numeric(),size=integer(),leading_edge_n=integer())};u<-merge(pp,g[,.(pathway_id,ES,NES,pval,size,leading_edge_n)],by="pathway_id",all.x=TRUE);u[,c("analysis","omitted_donor","healthy_donors","crohn_donors","tested_genes","mapped_ranked_genes","model_status","direction"):=list(name,omit,nh,nc,sum(k),nrow(t),ifelse(is.na(NES),"PATHWAY_NOT_TESTABLE","ESTIMABLE"),ifelse(is.na(NES),"NOT_ASSESSABLE",ifelse(NES>0,"CROHN_HIGHER","CROHN_LOWER")))];list(ok=TRUE,x=u)}
metas<-list.files(W,pattern="^human_.*_meta.tsv$",full.names=TRUE);names<-vapply(metas,function(f)fread(f,nrows=1)$analysis[1],character(1));F<-list();L<-list();T<-list()
for(i in seq_along(names)){n<-names[i];a<-tryCatch(fit(n,"NONE",FALSE,i*100),error=function(e)list(ok=FALSE,why=paste0("MODEL_ERROR:",conditionMessage(e)),nh=NA,nc=NA));if(a$ok)x<-a$x else{message("FIT_FAIL ",n," ",a$why);next};F[[length(F)+1]]<-x
 if(grepl("__Subtype__",n,fixed=TRUE)){m<-fread(metas[i]);for(j in seq_len(nrow(m))){dd<-m$donor[j];b<-tryCatch(fit(n,dd,FALSE,i*100+j),error=function(e)list(ok=FALSE,why=paste0("MODEL_ERROR:",conditionMessage(e)),nh=NA,nc=NA));if(b$ok)y<-b$x else{lin<-strsplit(n,"__",fixed=TRUE)[[1]][1];y<-copy(P[lineage==lin]);y[,c("analysis","omitted_donor","healthy_donors","crohn_donors","NES","pval","model_status","direction"):=list(n,dd,b$nh,b$nc,NA,NA,b$why,"NOT_ESTIMABLE")]};L[[length(L)+1]]<-y};tt<-tryCatch(fit(n,"NONE",TRUE,i*100+99),error=function(e)list(ok=FALSE,why=paste0("MODEL_ERROR:",conditionMessage(e)),nh=NA,nc=NA));if(tt$ok)z<-tt$x else{lin<-strsplit(n,"__",fixed=TRUE)[[1]][1];z<-copy(P[lineage==lin]);z[,c("analysis","healthy_donors","crohn_donors","NES","pval","model_status","direction"):=list(n,tt$nh,tt$nc,NA,NA,tt$why,"NOT_ESTIMABLE")]};T[[length(T)+1]]<-z}}
F<-rbindlist(F,fill=TRUE);F[,BH_q:=NA_real_];F[grepl("__Subtype__",analysis,fixed=TRUE),BH_q:=p.adjust(pval),by=lineage];L<-rbindlist(L,fill=TRUE);B<-F[grepl("__Subtype__",analysis,fixed=TRUE),.(lineage,analysis,frozen_program_id,full_NES=NES)];L<-merge(L,B,by=c("lineage","analysis","frozen_program_id"),all.x=TRUE);L[,direction_match_full:=fifelse(is.na(NES),"NOT_ESTIMABLE",fifelse(sign(NES)==sign(full_NES),"YES","NO"))];T<-rbindlist(T,fill=TRUE)
fwrite(F,file.path(W,"phase7_human_results.tsv"),sep="\t",na="");fwrite(L,file.path(W,"phase7_human_lodo.tsv"),sep="\t",na="");fwrite(T,file.path(W,"phase7_human_treatment.tsv"),sep="\t",na="");cat("HUMAN_DONE ",nrow(F)," ",nrow(L)," ",nrow(T),"\n",sep="")